using System;using System.Linq;using System.IO;using System.Web.Script.Serialization;
class QuotaLifecycleTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static string Response(object reset,int used=0){return new JavaScriptSerializer().Serialize(new{result=new{rateLimits=new{primary=new{windowDurationMins=300,usedPercent=used,resetsAt=reset}}}});}
 [STAThread]static int Main(string[] args){if(args.Length>0&&args[0]=="exec"){bool isolated=args.Contains("--ignore-user-config")&&args.Contains("--ephemeral")&&args.Contains("read-only")&&args.Contains("shell_tool")&&Environment.GetEnvironmentVariable("OPENAI_API_KEY")==null&&Path.GetFileName(Environment.CurrentDirectory).StartsWith("conan-quota-wake-");return isolated?0:19;}var now=new DateTime(2026,10,24,4,0,0,DateTimeKind.Utc);double unix=(now-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds;
 try{var pending=CodexQuotaSnapshot.Parse(Response(null),now);Check(pending.Windows.Count==1&&pending.Remaining(300,now)==100,"fresh unused window with no reset timestamp retains remaining quota");Check(CodexQuotaReader.Countdown(pending,300,now).Contains("首次"),"unused window explicitly awaits first request");Check(TaskbarPainter.QuotaValue(pending,300,new TaskbarAppearance(),now).Contains("待启动"),"taskbar distinguishes pending cycle");}catch(Exception){Check(false,"fresh unused window with no timestamp must parse");}
 try{var elapsed=CodexQuotaSnapshot.Parse(Response(unix-5,37),now);Check(elapsed.Windows.Count==1&&!elapsed.Remaining(300,now).HasValue,"expired used window retained without inventing recovered quota");Check(TaskbarPainter.QuotaValue(elapsed,300,new TaskbarAppearance(),now)=="待核验","expired used window remains unconfirmed");}catch(Exception){Check(false,"expired official window must not be discarded");}
 var cfg=new CodexQuotaConfig();var reader=new CodexQuotaReader();cfg.Enabled=false;Check(reader.Sample(cfg).State.Contains("关闭"),"quota master switch disables query");
 var sub=new CodexSubscriptionConfig{ExpiresLocal="2026-10-31T12:00"};Check(!sub.Enabled&&sub.Observe(now)==null,"subscription reminders default off");sub.Enabled=true;Check(sub.Observe(new DateTime(2026,10,24,11,59,59))==null,"no early reminder before threshold");Check(sub.Observe(new DateTime(2026,10,24,12,0,0)).Contains("7天"),"seven day reminder uses actual remaining duration");Check(sub.Observe(new DateTime(2026,10,24,12,1,0))==null,"same point does not repeat");var saved=new JavaScriptSerializer().Deserialize<CodexSubscriptionConfig>(new JavaScriptSerializer().Serialize(sub));Check(saved.Observe(new DateTime(2026,10,24,12,2,0))==null,"subscription dedup survives restart");Check(saved.Observe(new DateTime(2026,10,30,12,0,0))!=null&&saved.Sent.Count==3,"missed points coalesce on resume");Check(CodexSubscriptionConfig.ParseDays("0, 2, 5, 14").SequenceEqual(new[]{0,2,5,14}),"custom multiple reminder days include expiry day");bool invalid=false;try{CodexSubscriptionConfig.ParseDays("1.5");}catch(ArgumentException){invalid=true;}Check(invalid,"fractional days rejected");saved.ReminderDays.Add(0);Check(saved.Observe(new DateTime(2026,10,31,12,0,0)).Contains("已到达"),"expiry point fires without claiming billing status");Check(saved.Observe(new DateTime(2026,11,1))==null,"expired reminder does not loop");saved.ExpiresLocal="2026-11-30T12:00";Check(saved.Observe(new DateTime(2026,11,23,12,0,0))!=null,"renewed date creates independent dedup cycle");Check(new CodexSubscriptionConfig{Enabled=true,ExpiresLocal="bad"}.Observe(now)==null,"invalid saved expiry stays unset");Check(new CodexQuotaConfig().BackgroundRefresh,"background read default preserves existing polling");
 var old=new CodexQuotaSnapshot{AccountKey="A",PlanType="pro",CheckedUtc=now.AddMinutes(-2)};old.Windows.Add(new CodexQuotaWindow{Minutes=10080,Remaining=20,ResetUtc=now.AddSeconds(-1)});var full=new CodexQuotaSnapshot{AccountKey="A",PlanType="pro",CheckedUtc=now};full.Windows.Add(new CodexQuotaWindow{Minutes=10080,Remaining=100,ResetUtc=now.AddDays(7)});var wake=new CodexWakeConfig();Check(wake.Reserve(full,old,now)==null&&wake.Attempts.Count==0,"auto wake disabled by default");wake.Enabled=true;Check(wake.Reserve(full,old,now)==null&&wake.CandidateKeys.Count==1&&wake.Attempts.Count==0,"first recovered reading only creates confirmation candidate");var full2=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(full));full2.CheckedUtc=now.AddMinutes(1);full2.Windows[0].ResetUtc=now.AddMinutes(1).AddDays(7);Check(wake.Reserve(full2,full,full2.CheckedUtc)!=null&&wake.Attempts.Count==1,"second official reading reserves one request before execution");var persisted=new JavaScriptSerializer().Deserialize<CodexWakeConfig>(new JavaScriptSerializer().Serialize(wake));Check(persisted.Reserve(full2,full,full2.CheckedUtc)==null,"attempt survives restart without retry");full2.AccountKey="B";Check(new CodexWakeConfig{Enabled=true}.Reserve(full2,old,full2.CheckedUtc)==null,"account switch never auto wakes");full2.AccountKey="A";full2.PlanType="";Check(new CodexWakeConfig{Enabled=true}.Reserve(full2,old,full2.CheckedUtc)==null,"API key or unknown plan never auto wakes");full2.PlanType="pro";full2.RequiresAuthorization=true;Check(new CodexWakeConfig{Enabled=true}.Reserve(full2,old,full2.CheckedUtc)==null,"untrusted quota result cannot wake");full2.RequiresAuthorization=false;Check(full.Windows[0].PendingStart(now),"unused full length reset moving with sample time stays pending");Check(CodexQuotaReader.Countdown(full2,10080,full2.CheckedUtc).Contains("首次"),"moving unused reset does not fabricate anchored countdown");var repeatCfg=new CodexQuotaConfig{LastObserved=full};Check(new CodexQuotaReader().ObserveResets(full2,repeatCfg,full2.CheckedUtc).Length==0,"moving unused windows do not repeatedly announce reset");var recoveredCfg=new CodexQuotaConfig{LastObserved=old};var detected=new CodexQuotaReader().ObserveResets(full,recoveredCfg,now);Check(detected.Length==1&&detected[0].AwaitingStart,"quota recovery recorded separately from cycle start");Check(detected[0].Report().Contains("尚未启动"),"recovery history does not claim a fixed new reset time");string minimal=CodexQuotaReader.MinimalArguments("gpt-test-mini","low",@"C:\Temp\probe");Check(minimal.Contains("--ignore-user-config")&&minimal.Contains("--ephemeral")&&minimal.Contains("--disable shell_tool")&&minimal.Contains("project_doc_max_bytes=0"),"minimal request ignores projects tools and persistent chats");bool injected=false;try{CodexQuotaReader.MinimalArguments("bad;command","low",@"C:\Temp");}catch(ArgumentException){injected=true;}Check(injected,"model command injection rejected");Check(CodexQuotaReader.AccountPlan(new System.Collections.Generic.Dictionary<string,object>{{"account",new System.Collections.Generic.Dictionary<string,object>{{"type","chatgpt"},{"planType","pro"}}}})=="pro","official plan type parsed without guessing expiry");
 var pausedReader=new CodexQuotaReader();var pausedConfig=new CodexQuotaConfig{BackgroundRefresh=false};pausedReader.Sample(pausedConfig);System.Threading.Thread.Sleep(100);Check(!pausedReader.Sample(pausedConfig).RequiresAuthorization&&pausedReader.Status.Contains("等待"),"background switch prevents process launch");pausedReader.RefreshNow();pausedReader.Sample(pausedConfig);System.Threading.Thread.Sleep(200);Check(pausedReader.Sample(pausedConfig).RequiresAuthorization,"manual refresh remains available with background polling off");
 string originalKey=Environment.GetEnvironmentVariable("OPENAI_API_KEY");try{Environment.SetEnvironmentVariable("OPENAI_API_KEY","test-only-dummy");var method=typeof(CodexQuotaReader).GetMethod("RunMinimalRequest",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);string result=(string)method.Invoke(null,new object[]{System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,Path.GetTempPath(),"gpt-test-mini","low"});Check(result.Contains("已完成"),"isolated fake CLI receives safe flags empty workspace and no API key");}finally{Environment.SetEnvironmentVariable("OPENAI_API_KEY",originalKey);}
 File.WriteAllText(Path.Combine(args[0],"quota-lifecycle-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures}));return failures==0?0:1;}
}
